/* Offline cache. Generated by build.py from templates/sw.js; don't edit sw.js directly.
   Opens instantly from the cache (works with no signal), then quietly fetches
   fresh copies in the background for next time. */
const VERSION = "ea85ee87b8";
const FILES = [
  "./",
  "index.html",
  "site.css",
  "manifest.webmanifest",
  "icons/icon-192.png",
  "icons/apple-touch-icon.png",
  "slides/",
  "slides/index.html",
  "reading-list/",
  "reading-list/index.html",
  "slides/images/02_Olympia-metope_Heracles-Atlas_EB1911.jpg",
  "slides/images/04_Cranach_Hercules-and-Atlas.jpg",
  "slides/images/05_Sargent_Atlas-and-the-Hesperides.jpg",
  "slides/images/06_Leighton_Garden-of-the-Hesperides.jpg",
  "slides/images/08_Guercino_Atlas-celestial-globe.jpg",
  "slides/images/10_Cranach-workshop_Hercules-and-Hydra.jpg"
];

self.addEventListener("install", e => {
  e.waitUntil(caches.open(VERSION).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== VERSION && k !== "fonts").map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", e => {
  if (e.request.method !== "GET") return;
  const url = new URL(e.request.url);

  if (url.origin === location.origin) {
    e.respondWith(caches.open(VERSION).then(async cache => {
      const hit = await cache.match(e.request, { ignoreSearch: true });
      const fresh = fetch(e.request)
        .then(r => { if (r.ok) cache.put(e.request, r.clone()); return r; })
        .catch(() => hit);
      return hit || fresh;
    }));
    return;
  }

  // Google Fonts: keep a copy so the deck looks right offline
  if (/^fonts\.(googleapis|gstatic)\.com$/.test(url.hostname)) {
    e.respondWith(caches.open("fonts").then(async cache => {
      const hit = await cache.match(e.request);
      if (hit) return hit;
      const r = await fetch(e.request);
      cache.put(e.request, r.clone());
      return r;
    }));
  }
});
